import React, { useState } from "react";
import Layout from "../components/layout";
import TOC from "../components/toc"
import { graphql } from "gatsby";
import { JsonSchemaViewer } from "@stoplight/json-schema-viewer";
import "@stoplight/mosaic/styles.css";
import "@stoplight/mosaic/themes/default.css";
import Learn from "../images/learn.svg";
import { Link } from "gatsby";
import { FiArrowRight } from "react-icons/fi";


const DocPage = ({ data, pageContext }) => {

  const [selectedSchema, setSelectedSchema] = useState(0)
  const schemas = pageContext.schemaData
  const schemasThere = schemas.length > 0
  const packages = pageContext.packageData
  const packagesThere = packages.length > 0
  return (
    <Layout>
      <div className="container doc-page mx-auto mb-20 mt-32">
      <div className="flex flex-col-reverse items-start md:flex-row md:justify-between md:items-end mb-16 mx-4 ">
      <div className="flex flex-col">
        {/* <span className="font-outfit text-wpGreen-900 font-extrabold text-xl">
          Learn
        </span> */}
        <span class="font-header text-green-500 font-extrabold text-xl"><Link to='/'>WATERPATH TOOLKIT</Link> / <Link to='/learn'>LEARN</Link></span>
        <span className="font-body text-blue-500 font-extralight text-[5.5rem] leading-none tracking-tight -ml-[10px]">
          {pageContext.title}
        </span>
      </div>
      <div className="hidden md:flex h-[200px]">
        <Learn />
      </div>
    </div>
        <div className={`mt-36 w-full grid grid-flow-row-dense mx-auto font-body text-blue-500  ${!schemasThere && !packagesThere && "md:grid-cols-3 gap-4"}`}>
          {(!schemasThere && !packagesThere) && <TOC content={data.markdownRemark.tableOfContents}/>}
          <div className={`main-content font-body text-blue-500  ${!schemasThere && !packagesThere && "md:col-span-2"}`} dangerouslySetInnerHTML={{ __html: data.markdownRemark.html }} />
        </div>
        {schemasThere && (
          <>
            <p className="mt-12 font-body text-blue-500">Navigate the documented data properties by clicking on each schema below: </p>
            <div className="mt-12 w-full grid grid-flow-row-dense md:grid-cols-4 gap-4 mx-auto">

              {(schemas.map((schema, i) => {
                const data = JSON.parse(schema.node.data.raw)
                return <div>
                  <a href="#viewer" onClick={() => setSelectedSchema(i)} className={"m-auto h-[120px] text-center pt-8 text-lg line-clamp-2 align-middle max-w-sm p-6 rounded-lg shadow-sm bg-sand-500 hover:bg-sand-800" + ((i === selectedSchema) ? ' bg-sand-800' : '')}>

                    <h5 className="mb-12 font-bold tracking-tight text-blue-500">{data.title}</h5>
                  </a>
                </div>
              })
              )}


            </div>
            <div id="viewer" className="mt-24 w-full mx-auto font-body ">
              <pre>
                <JsonSchemaViewer
                  name="Schema viewer"
                  schema={JSON.parse(schemas[selectedSchema].node.data.raw)}
                  expanded={true}
                  hideTopBar={false}
                  emptyText="No schema defined"
                  defaultExpandedDepth={2}
                />
              </pre>
            </div>
          </>
        )}
        {packagesThere && (
          <>
          <div className="mt-12 w-full  mx-auto">

{(packages.map((p, i) => {
  data = p.node.data
  return <div>
    <a href={'https://github.com/WaterPath-Project/waterpath-data/tree/main/'+data.parent+''} className={"block group mb-6 w-full pt-8 text-lg line-clamp-2 align-middle p-6 rounded-lg shadow-sm bg-white border hover:border-sand-100" }>
    <div className="relative">        <div className="absolute top-0 right-0"></div>
      <h5 className="font-bold tracking-tight text-blue-500 flex flex-row items-center"><span className="group-hover:underline mr-1">{data.title}</span> <FiArrowRight className="text-sand-500 group-hover:text-blue-500"/></h5>
      <p className="font-body text-blue-500 text-sm">{data.description}</p>
      </div>
      <div className="flex justify-between relative">
      <div className="pt-5 text-sand-700 text-xs">
        <span className="font-bold">Sources:</span> <ul>{data.source.map((s) => {return <li><a href={s.path} target="_blank">{s.title}</a></li>})}</ul>
        </div>

        </div>
    </a>
  </div>
})
)}
</div>
          </>
        )}
      </div>
    </Layout>
  )
}


export const query = graphql`
  query MarkdownById($id: String!) {
    markdownRemark(id: { eq: $id }) {
      html
      tableOfContents
      fields {
        docName
        repo
      }
    }
  }
`


export default DocPage

export const Head = () => <title>WaterPath Toolkit</title>
